const review = $input.first().json;
const stars = review.starRating;
const comment = (review.comment || "").toLowerCase();

let action = "notify_admin";
let reply = "";
let priority = "normal";

if (stars >= 4) {
  action = "auto_reply";
  reply = "\u00a1Gracias por tu rese\u00f1a! Nos alegra que hayas disfrutado de Golden Harvest. Tu opini\u00f3n nos motiva a seguir mejorando.";
} else {
  if (comment.includes("demora") || comment.includes("roto") || comment.includes("p\u00e9simo") || comment.includes("horrible")) {
    action = "urgent_admin";
    priority = "urgent";
  }
}

return [{
  json: {
    ...review,
    action,
    priority,
    suggested_reply: reply,
    reviewer_name: review.reviewer?.displayName || review.reviewerDisplayName || "Cliente",
    stars_numeric: typeof stars === 'number' ? stars : (["ONE", "TWO", "THREE", "FOUR", "FIVE"].indexOf(stars) + 1)
  }
}];

const reviews = $input.first().json.result?.reviews ?? [];
return reviews.map(r => ({
  json: {
    reviewId: `places_${r.time}`,
    reviewer: { displayName: r.author_name },
    starRating: ['ONE','TWO','THREE','FOUR','FIVE'][r.rating - 1],
    comment: r.text,
    source: 'places_api'
  }
}));

