// Expand the reviews array into individual items for splitInBatches
const reviews = $input.first().json.reviews;
return reviews.map(r => ({ json: r }));

// [TESIS] Generate polite Spanish reply — do NOT post to GMB
const review = $input.first().json;
const name = review.reviewer_name || review.reviewerDisplayName || 'Cliente';
const stars = review.stars_numeric || review.starRating;

let reply;
if (stars === 5) {
  reply = `\u00a1Muchas gracias ${name}! Nos alegra mucho que disfrutes de nuestros productos Golden Harvest. Tu opini\u00f3n es muy valiosa para nosotros.`;
} else {
  reply = `\u00a1Gracias ${name} por tu rese\u00f1a! Nos alegra que hayas disfrutado de Golden Harvest. Tu opini\u00f3n nos motiva a seguir mejorando.`;
}

return [{
  json: {
    ...review,
    tesis_reply: reply,
    tesis_action: 'reply_generated_not_posted',
    processed_at: new Date().toISOString()
  }
}];

// [TESIS] Format escalation summary — do NOT send email
const review = $input.first().json;
const name = review.reviewer_name || review.reviewerDisplayName || 'Cliente';
const stars = review.stars_numeric || review.starRating;
const isUrgent = review.priority === 'urgent';

const summary = {
  tipo: isUrgent ? 'URGENTE' : 'Atenci\u00f3n requerida',
  revisor: name,
  estrellas: stars,
  comentario: review.comment,
  sugerencia: `Contactar a ${name} para resolver su experiencia negativa y ofrecer compensaci\u00f3n si corresponde.`,
  tesis_action: 'escalation_formatted_not_emailed',
  processed_at: new Date().toISOString()
};

return [{ json: { ...review, escalation_summary: summary } }];

// [TESIS] Collect all processed reviews and write to file
const allItems = $input.all();
const results = allItems.map(item => item.json);

const positive = results.filter(r => r.action === 'auto_reply');
const negative = results.filter(r => r.action !== 'auto_reply');
const urgent = results.filter(r => r.priority === 'urgent');

const output = {
  timestamp: new Date().toISOString(),
  workflow: '03. Google Maps Review Management',
  modo: 'TESIS (simulado)',
  summary: {
    total: results.length,
    positivas: positive.length,
    negativas: negative.length,
    urgentes: urgent.length
  },
  reviews: results
};

const fs = require('fs');
const path = '/home/node/.n8n/reviews_processed.json';
fs.writeFileSync(path, JSON.stringify(output, null, 2));

console.log(`[WF3 TESIS] Reviews procesadas: ${results.length} total`);
console.log(`  Positivas: ${positive.length} | Negativas: ${negative.length} | Urgentes: ${urgent.length}`);
console.log(`  Archivo escrito en: ${path}`);

return [{ json: output.summary }];
